-- =============================================================================
-- Planet Blitz M4 — Phase E · E2 NPC 시드 기지 20개 (계획 §4 Phase E2 · §5 · AC4)
-- =============================================================================
-- 근거: GDD §8("배치전: PvP 해금 첫 5회 NPC 시드 기지 대상"), 계획 §5(NPC 난이도 분포
--   20개 하위~중위), 핸드오프 phase-e-contract.md 계약 1(NPC 시드 기지).
--
-- 설계 결정(문서화):
--   ⓐ auth.users FK 처리 — **마이그레이션에서 auth.users 직접 insert(고정 UUID)** 를
--     택했다(계약 1 옵션 ⓐ). 근거: (1) admin API 는 이 워커/마이그레이션 컨텍스트에서
--     쓸 수 없다(서버 키·HTTP 필요). (2) NPC 는 절대 로그인하지 않으므로 GoTrue 인증
--     컬럼(encrypted_password·토큰 등)이 전부 null 이어도 무해하다 — 우리가 필요한 건
--     profiles.id → auth.users(id) 참조 무결성뿐이다. (3) auth.users 의 NOT NULL 컬럼은
--     id·is_sso_user·is_anonymous 3개뿐(원격 실측)이라 최소 insert 가 안전하다.
--     고정 UUID `000000e5-ed00-4000-8000-0000000000NN`(NN=01..20)로 재실행/클라 조인
--     (seedBases.ts SEED_BASE_PROFILE_IDS)이 결정론적이다.
--   • layout 정본 = 이 마이그레이션(리드 판정 2026-07-17). data/seedBases.ts 는 layout 을
--     이중 정의하지 않고 표시 메타(한글 이름·난이도·설명)만 갖는다 — 드리프트 원천 차단.
--     클라는 NPC layout 을 get_placement_targets()/get_invasion_targets() 반환값으로만
--     렌더·재실행한다. 이 파일의 20개 layout 은 e-client normalizeLayout(src/ui/
--     defenseCommand.ts) 규칙 + 예산 20 이하를 정적 생성기로 검증했다(전부 통과).
--   • 난이도: NN=01(가장 쉬움, 예산 2)~20(가장 어려움, 예산 20). 초기 rank = 21-NN
--     (#01=rank20 … #20=rank1). 하위(01~07)·중하(08~14)·중위(15~20).
--   • defense_id 앵커: ladder.defense_id 를 NPC 방어 행으로 백필한다(고정 UUID
--     `000000de-f000-4000-8000-0000000000NN`). 실유저의 defense_id 백필 여부는 풍화
--     마이그레이션(_weathering) 주석에서 결정·문서화(결론: 실유저는 미채움 — 매치메이킹은
--     defenses.active 조인을 쓰고, DELETE 우회는 정책으로 봉인하므로 앵커 불필요).
--
-- 재실행 안전성: 모든 insert 는 on conflict do nothing(고정 UUID 기준), 스키마 패치는
-- if not exists / create or replace 로 부분 실패 후 재적용이 에러 없이 수렴한다.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- 0. profiles.is_npc 컬럼 + 서버 권위 가드 확장
-- -----------------------------------------------------------------------------
-- 배치전(get_placement_targets)·매치 카운트가 NPC 를 식별할 마커. 서버(시드)만 true 로
-- 세팅하고, 클라이언트가 자기 행을 is_npc:=true 로 위장(배치전 타깃 사칭)하지 못하게
-- 가드에 flagged 와 동일 패턴으로 고정한다.
alter table public.profiles add column if not exists is_npc boolean not null default false;

create index if not exists profiles_is_npc_idx on public.profiles (is_npc) where is_npc;

create or replace function public.guard_profiles_client_write()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if not public.is_service_role() then
    new.flagged := old.flagged;
    new.is_npc := old.is_npc;  -- Phase E: NPC 마커 위장 차단.
  end if;
  return new;
end;
$$;
-- 트리거(trg_profiles_guard, before update)는 초기 스키마에서 이미 정의됨 — 함수 교체로 반영.

-- =============================================================================
-- 1. 시드 데이터 (auth.users → profiles → ships → defenses → ladder 순, FK 안전)
-- =============================================================================

-- ===== auth.users (20 NPC) =====
on conflict (id) do nothing;

-- ===== profiles (is_npc=true, save.credits=0) =====
on conflict (id) do nothing;

-- ===== ships (표시용 미러, slot 0 — get_*_targets 의 ship_summary) =====
on conflict (profile_id, slot) do nothing;

-- ===== defenses (layout 정본 · maintenance 100 · active · budget_spent=실제 layout 비용) =====
on conflict (id) do nothing;

-- ===== ladder (초기 순위 1~20 · placed=true · defense_id 앵커 백필) =====
on conflict (profile_id) do nothing;
